# Count clusters - positions where an 8 has other 8s nearby
def get_cluster(r, c, threshold=2):
    """Find all 8s within Manhattan distance threshold from (r,c)"""
    cluster = set()
    for dr in range(-threshold, threshold+1):
        for dc in range(-threshold, threshold+1):
            pr, pc = r + dr, c + dc
            if 0 <= pr < h and 0 <= pc < w:
                if test_input[pr][pc] == 8:
                    cluster.add((pr, pc))
    return cluster

clusters = []
seen = set()
for r, c in positions_8:
    if (r, c) in seen:
        continue
    cluster = get_cluster(r, c, threshold=2)
    cluster_list = list(cluster)
    # Only consider "real" clusters (size >= 2)
    if len(cluster_list) >= 2:
        clusters.append(set(cluster_list))

print(f"Found {len(clusters)} clusters of size >= 2")
for i, cluster in enumerate(clusters):
    print(f"  Cluster {i}: {len(cluster)} cells at {sorted(cluster)}")

